use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn generate_owl_output (ontology : & OwlOntology) -> Result < () > { let mut owl = String :: new () ; owl . push_str ("@prefix owl: <http://www.w3.org/2002/07/owl#> .\n") ; owl . push_str ("@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n") ; owl . push_str ("@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n") ; owl . push_str ("@prefix lmdfb: <http://split-decls-rs.org/lmdfb#> .\n\n") ; owl . push_str ("<http://split-decls-rs.org/lmdfb> rdf:type owl:Ontology ;\n") ; owl . push_str ("    rdfs:label \"LMDFB Lattice Ontology\" ;\n") ; owl . push_str ("    rdfs:comment \"Ontology for Rust ecosystem lattice mapping\" .\n\n") ; owl . push_str ("# Classes\n") ; for class in & ontology . classes { owl . push_str (& format ! ("lmdfb:{} rdf:type owl:Class .\n" , class)) ; } owl . push_str ("\n") ; owl . push_str ("# Properties\n") ; for property in & ontology . properties { owl . push_str (& format ! ("lmdfb:{} rdf:type owl:ObjectProperty" , property)) ; if let Some (domain) = ontology . domains . get (property) { owl . push_str (& format ! (" ;\n    rdfs:domain lmdfb:{}" , domain)) ; } if let Some (range) = ontology . ranges . get (property) { owl . push_str (& format ! (" ;\n    rdfs:range lmdfb:{}" , range)) ; } owl . push_str (" .\n\n") ; } owl . push_str ("# Sample Individuals and Relations\n") ; for (i , (subject , predicate , object)) in ontology . triples . iter () . take (100) . enumerate () { if predicate == "rdf:type" { owl . push_str (& format ! ("lmdfb:{} {} lmdfb:{} .\n" , subject , predicate , object)) ; } else if object . starts_with ('"') { owl . push_str (& format ! ("lmdfb:{} lmdfb:{} {} .\n" , subject , predicate , object)) ; } else { owl . push_str (& format ! ("lmdfb:{} lmdfb:{} lmdfb:{} .\n" , subject , predicate , object)) ; } } fs :: write ("lmdfb_ontology.owl" , owl) ? ; Ok (()) }